package com.fasterxml.jackson.databind.ser.impl;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.io.JsonParser;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.ser.ObjectIdWriter;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class WritableObjectId_writeAsField_TriageGen1Test {

    private JsonGenerator gen;
    private SerializerProvider provider;
    private ObjectIdWriter w;
    private ObjectIdGenerator<?> generator;
    private WritableObjectId writableObjectId;

    @Before
    public void setUp() {
        gen = mock(JsonGenerator.class);
        provider = mock(SerializerProvider.class);
        w = mock(ObjectIdWriter.class);
        generator = mock(ObjectIdGenerator.class);
        writableObjectId = new WritableObjectId(generator);

        // Set an ID via generateId to simulate state
        when(generator.generate(any())).thenReturn("test-id-123");
        writableObjectId.generateId(new Object());
    }

    @Test
    public void testWriteAsField_WhenCanWriteObjectIdIsTrue() throws IOException {
        // Arrange
        when(gen.canWriteObjectId()).thenReturn(true);

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen).writeObjectId("test-id-123");
        verify(gen, never()).writeFieldName(any(SerializableString.class));
        verify(w, never()).serializer; // Accessing field is tricky with mock, but we check behavior
        assertTrue(writableObjectId.isWritten());
    }

    @Test
    public void testWriteAsField_WhenCanWriteObjectIdIsFalse_AndPropertyNameNotNull() throws IOException {
        // Arrange
        when(gen.canWriteObjectId()).thenReturn(false);
        SerializableString name = mock(SerializableString.class);
        w.propertyName = name;

        // Mock the serializer inside ObjectIdWriter
        com.fasterxml.jackson.databind.JsonSerializer<Object> serializer = mock(com.fasterxml.jackson.databind.JsonSerializer.class);
        w.serializer = serializer;

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen).writeFieldName(name);
        verify(serializer).serialize(eq("test-id-123"), eq(gen), eq(provider));
        assertTrue(writableObjectId.isWritten());
    }

    @Test
    public void testWriteAsField_WhenCanWriteObjectIdIsFalse_AndPropertyNameIsNull() throws IOException {
        // Arrange
        when(gen.canWriteObjectId()).thenReturn(false);
        w.propertyName = null;

        // Act
        writableObjectId.writeAsField(gen, provider, w);

        // Assert
        verify(gen, never()).writeFieldName(any(SerializableString.class));
        verify(gen, never()).writeObjectId(anyString());
        assertTrue(writableObjectId.isWritten());
    }
}
